TLM.f("Tempora/Pent20-5",{"officium":"Feria Sexta infra Hebdomadam XX post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent20-0","from":{"Introitus":"Tempora/Pent20-0","Oratio":"Tempora/Pent20-0","Lectio":"Tempora/Pent20-0","Graduale":"Tempora/Pent20-0","Evangelium":"Tempora/Pent20-0","Offertorium":"Tempora/Pent20-0","Secreta":"Tempora/Pent20-0","Communio":"Tempora/Pent20-0","Postcommunio":"Tempora/Pent20-0"},"sections":{"Introitus":[{"k":"ref","la":"Dan 3:31; 31:29; 31:35"},{"k":"text","la":"Omnia, quæ fecísti nobis, Dómine, in vero judício fecísti, quia peccávimus tibi et mandátis tuis non obœdívimus: sed da glóriam nómini tuo, et fac nobíscum secúndum multitúdinem misericórdiæ tuæ."},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Omnia, quæ fecísti nobis, Dómine, in vero judício fecísti, quia peccávimus tibi et mandátis tuis non obœdívimus: sed da glóriam nómini tuo, et fac nobíscum secúndum multitúdinem misericórdiæ tuæ."}],"Oratio":[{"k":"text","la":"Largíre, quǽsumus, Dómine, fidélibus tuis indulgéntiam placátus et pacem: ut páriter ab ómnibus mundéntur offénsis, et secúra tibi mente desérviant."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios"},{"k":"ref","la":"Ephes 5:15-21"},{"k":"text","la":"Fratres: Vidéte, quómodo caute ambulétis: non quasi insipiéntes, sed ut sapiéntes, rediméntes tempus, quóniam dies mali sunt. Proptérea nolíte fíeri imprudéntes, sed intellegéntes, quæ sit volúntas Dei. Et nolíte inebriári vino, in quo est luxúria: sed implémini Spíritu Sancto, loquéntes vobismetípsis in psalmis et hymnis et cánticis spirituálibus, cantántes et psalléntes in córdibus vestris Dómino: grátias agéntes semper pro ómnibus, in nómine Dómini nostri Jesu Christi, Deo et Patri. Subjecti ínvicem in timóre Christi."}],"Graduale":[{"k":"ref","la":"Ps 144:15-16"},{"k":"text","la":"Oculi ómnium in te sperant, Dómine: et tu das illis escam in témpore opportúno. V. Aperis tu manum tuam: et imples omne ánimal benedictióne. Allelúja, allelúja"},{"k":"ref","la":"Ps 107:2"},{"k":"text","la":"Parátum cor meum, Deus, parátum cor meum: cantábo, et psallam tibi, glória mea. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 4:46-53"},{"k":"text","la":"In illo témpore: Erat quidam régulus, cujus fílius infirmabátur Caphárnaum. Hic cum audísset, quia Jesus adveníret a Judǽa in Galilǽam, ábiit ad eum, et rogábat eum, ut descénderet et sanáret fílium ejus: incipiébat enim mori. Dixit ergo Jesus ad eum: Nisi signa et prodígia vidéritis, non créditis. Dicit ad eum régulus: Dómine, descénde, priúsquam moriátur fílius meus. Dicit ei Jesus: Vade, fílius tuus vivit. Crédidit homo sermóni, quem dixit ei Jesus, et ibat. Jam autem eo descendénte, servi occurrérunt ei et nuntiavérunt, dicéntes, quia fílius ejus víveret. Interrogábat ergo horam ab eis, in qua mélius habúerit. Et dixérunt ei: Quia heri hora séptima relíquit eum febris. Cognóvit ergo pater, quia illa hora erat, in qua dixit ei Jesus: Fílius tuus vivit: et crédidit ipse et domus ejus tota."}],"Offertorium":[{"k":"ref","la":"Ps 136:1"},{"k":"text","la":"Super flúmina Babylónis illic sédimus et flévimus: dum recordarémur tui, Sion."}],"Secreta":[{"k":"text","la":"Cœléstem nobis prǽbeant hæc mystéria, quǽsumus, Dómine, medicínam: et vítia nostri cordis expúrgent."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 118:49-50"},{"k":"text","la":"Meménto verbi tui servo tuo, Dómine, in quo mihi spem dedísti: hæc me consoláta est in humilitáte mea."}],"Postcommunio":[{"k":"text","la":"Ut sacris, Dómine, reddámur digni munéribus: fac nos, quǽsumus, tuis semper obœdíre mandátis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"0f20c771e95c39e3":{"t":"Dn 3, 31 i 29 i 35, Ps 118, 1\n(Dn 3, 31 i 29 i 35) Imao si pravo, Gospodine, sa svim što si nam učinio, jer smo sagriješili tebi i tvojim se zapovijedima nismo pokoravali. Ali proslavi ime svoje i učini s nama po mnoštvu smilovanja svoga. (Ps 118, 1) Blago onima koji idu neokaljanim putem, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Dn 3, 31 i 29 i 35) Imao si pravo, Gospodine, sa svim što si nam učinio, jer smo sagriješili tebi i tvojim se zapovijedima nismo pokoravali. Ali proslavi ime svoje i učini s nama po mnoštvu smilovanja svoga."},"5365a1e93a24af63":{"t":"<i>Pomolimo se</i>.\nUdijeli, molimo, Gospodine, umilostivljen svojim vjernicima oproštenje i mir, da se očiste od svih grijeha i da ti bez straha služe.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"0c81453cd0df884c":{"t":"Ef 5, 15-21\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo, dobro pazite kako živite. Iskoristite vrijeme, ne kao ludi nego kao mudri, jer su dani zli. Zato nemojte biti nerazumni, nego shvatite što je volja Božja. Ne opijajte se vinom, jer se u njemu nalazi razuzdanost, nego se napunite Duha Svetoga. Molite zajedno psalme, himne i duhovne pjesme. Pjevajte i slavite Gospodina u svojim srcima. Na svemu uvijek zahvaljujte u ime Gospodina našega Isusa Krista Bogu Ocu. Pokoravajte se jedan drugome u strahu Kristovu."},"e0c721c5c344b0f6":{"t":"Ps 144, 15-16\nOči sviju uzdaju se u tebe, Gospodine, i ti im daješ hranu u pravo vrijeme. Ti otvaraš svoju ruku i puniš blagoslovom sve što živi.\n\nPs 107, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nSpremno je srce moje, Bože, spremno je srce moje, pjevat ću i pripjevat ću psalme slavi tvojoj. <i>Aleluja</i>.","v":"∅ → v"},"2cb888720d7cc4b1":{"t":"Iv 4, 46-53\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme bolovao je u Kafarnaumu sin nekoga kraljevskog činovnika. Kad je ovaj čuo, da je Isus došao iz Judeje u Galileju, pođe k njemu i zamoli ga da dođe i da mu ozdravi sina koji bijaše na umoru. Isus mu reče: Ako ne vidite znakova i čudesa, ne vjerujete. Kraljevski činovnik ponovi: Gospodine, dođi prije nego umre moj sin! Isus mu reče: Pođi! tvoj sin živi. Čovjek povjerova Isusovoj riječi i pođe. Kad se on vraćao kući dođu mu u susret sluge koji mu jave: Sin je tvoj ozdravio. On ih upita za vrijeme, kad mu je bilo bolje. Sluge mu odgovore: Jučer oko sedam sati pusti ga groznica. Tad otac upozna, da je to bilo u onaj sat kad mu Isus reče: Tvoj sin živi. I povjerova on i sav njegov dom."},"5516328e767399ed":{"t":"Ps 136, 1\nNa babilonskim rijekama sjedili smo i plakali sjećajući se tebe, Sione."},"488e4d4b595b9ff9":{"t":"Bila nam, molimo, Gospodine, ova otajstva nebeski lijek, i neka očiste opačine našega srca.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"1cbe7ebd0816089b":{"t":"Ps 118, 49-50\nSpomeni se svoje riječi slugi svojemu, Gospodine, po kojoj mi ulijevaš pouzdanje. U mojoj me nevolji utješi."},"9fd0f14ee37e2391":{"t":"<i>Pomolimo se</i>.\nDa bismo postali dostojni svetih darova, Gospodine, podaj, molimo, da budemo vazda poslušni tvojim zapovijedima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
